package com.greenocean.backend;
import com.greenocean.backend.wellbeing.service.PrivateWellbeing;
import com.greenocean.backend.auth.repository.UserRepository;
import com.greenocean.backend.auth.service.TokenService;
import com.greenocean.backend.account.service.AccountService;
import com.greenocean.backend.account.repository.AccountRepository;
import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional
class PhaseO1PrivateTest {
 @Autowired PrivateWellbeing s;@Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired AccountService archive;@Autowired AccountRepository accounts;
 @Autowired com.greenocean.backend.preference.repository.UserPreferencesRepository preferences;
 @Autowired tools.jackson.databind.ObjectMapper json;
 PhaseIFixtures.Actor a,b;
 @BeforeEach void setup(){PhaseIFixtures.region(db);a=PhaseIFixtures.member(db,users,tokens);b=PhaseIFixtures.member(db,users,tokens);}
 PrivateWellbeing.Writing writing(String body,long revision,UUID key){return new PrivateWellbeing.Writing("آرامش",body,"Mixed",List.of("خصوصی"),revision,key);}
 @Test @Tag("happy") void privateJournalLifecycleSearchAndRevision(){var row=s.write(a.id(),null,writing("متن فارسی Unicode 🌿",0,UUID.randomUUID()));UUID id=(UUID)row.get("id");assertThat(s.history(a.id(),"journal",20,0,"فارسی",false).get("items")).asList().hasSize(1);s.write(a.id(),id,writing("edited",0,null));assertThatThrownBy(()->s.write(a.id(),id,writing("stale",0,null))).isInstanceOf(ConflictException.class);assertThat(s.one(a.id(),"journal",id).get("body")).isEqualTo("edited");s.delete(a.id(),"journal",id);assertThatThrownBy(()->s.one(a.id(),"journal",id)).isInstanceOf(NotFoundException.class);}
 @Test @Tag("malicious") void noCrossOwnerReadEditDeleteOrSearch(){UUID id=(UUID)s.write(a.id(),null,writing("secret",0,UUID.randomUUID())).get("id");assertThatThrownBy(()->s.one(b.id(),"journal",id)).isInstanceOf(NotFoundException.class);assertThatThrownBy(()->s.write(b.id(),id,writing("stolen",0,null))).isInstanceOf(NotFoundException.class);assertThatThrownBy(()->s.delete(b.id(),"journal",id)).isInstanceOf(NotFoundException.class);assertThat(s.history(b.id(),"journal",20,0,"secret",false).get("items")).asList().isEmpty();}
 @Test @Tag("creative") void retryKeysAndBoundedPagination(){UUID key=UUID.randomUUID();var first=s.write(a.id(),null,writing("first",0,key));assertThat(s.write(a.id(),null,writing("replayed",0,key)).get("id")).isEqualTo(first.get("id"));assertThat(s.one(a.id(),"journal",(UUID)first.get("id")).get("body")).isEqualTo("first");for(int i=0;i<3;i++)s.write(a.id(),null,writing("row"+i,0,UUID.randomUUID()));assertThat(s.history(a.id(),"journal",2,0,"",false).get("hasMore")).isEqualTo(true);assertThat(s.history(a.id(),"journal",2,1,"",false).get("items")).asList().hasSize(2);assertThatThrownBy(()->s.history(a.id(),"journal",51,0,"",false)).isInstanceOf(IllegalArgumentException.class);}
 @Test @Tag("happy") void moodHistoryEditDeleteAndDescriptiveTimezoneSummary(){var row=s.mood(a.id(),null,new PrivateWellbeing.Mood("احساس ترکیبی","note",0,UUID.randomUUID()));UUID id=(UUID)row.get("id");s.mood(a.id(),id,new PrivateWellbeing.Mood("Quiet","edited",0,null));assertThatThrownBy(()->s.mood(b.id(),id,new PrivateWellbeing.Mood("Fake","",1,null))).isInstanceOf(NotFoundException.class);var day=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Tehran")).toString();assertThat(s.summary(a.id(),"Asia/Tehran",day,day).get("items")).asList().hasSize(1);s.delete(a.id(),"check-ins",id);assertThat(s.history(a.id(),"check-ins",20,0,"",false).get("items")).asList().isEmpty();}
 @Test @Tag("confused") void goalsDeriveOnlyFromActualStepsAndSupportPauseReopenArchive(){var row=s.goal(a.id(),null,new PrivateWellbeing.Goal("Walk","weekly","ACTIVE",0));UUID id=(UUID)row.get("id");row=s.step(a.id(),id,null,new PrivateWellbeing.Step("Choose time",false,0),false);assertThat(row.get("derivedProgress")).isEqualTo(0);assertThatThrownBy(()->s.goal(a.id(),id,new PrivateWellbeing.Goal("Walk","","COMPLETED",1))).isInstanceOf(ConflictException.class);UUID step=(UUID)((List<Map<String,Object>>)row.get("steps")).getFirst().get("id");row=s.step(a.id(),id,step,new PrivateWellbeing.Step("Choose time",true,1),false);assertThat(row.get("derivedProgress")).isEqualTo(100);s.goal(a.id(),id,new PrivateWellbeing.Goal("Walk","weekly","PAUSED",2));assertThatThrownBy(()->s.step(a.id(),id,step,new PrivateWellbeing.Step("stale",true,2),false)).isInstanceOf(ConflictException.class);s.goal(a.id(),id,new PrivateWellbeing.Goal("Walk","weekly","COMPLETED",3));s.goal(a.id(),id,new PrivateWellbeing.Goal("Walk","weekly","ACTIVE",4));s.goal(a.id(),id,new PrivateWellbeing.Goal("Walk","weekly","ARCHIVED",5));s.delete(a.id(),"goals",id);assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_goal_steps WHERE goal_id=?",Integer.class,id)).isZero();}
 void prompts(){for(int i=0;i<6;i++)db.update("INSERT INTO wellbeing_prompt_versions(revision,language,body,status,author_id,reviewer_id,review_note,reviewed_at) VALUES (1,'en',?,'PUBLISHED',?,?,'Synthetic isolated test review',CURRENT_TIMESTAMP)","Synthetic question "+i,a.id(),b.id());}
 @Test @Tag("happy") void threeDailyQuestionsPersistExactVersionsAndPartialAnswers(){prompts();var daily=s.daily(a.id(),"UTC","en");UUID set=(UUID)((Map<?,?>)daily.get("set")).get("id");assertThat(daily.get("items")).asList().hasSize(3);s.answer(a.id(),new PrivateWellbeing.Answer(set,1,"one optional answer",-1),false);assertThat(s.daily(a.id(),"UTC","fa").get("set")).isEqualTo(daily.get("set"));s.answer(a.id(),new PrivateWellbeing.Answer(set,1,"edited",0),false);assertThatThrownBy(()->s.answer(a.id(),new PrivateWellbeing.Answer(set,1,"stale",0),false)).isInstanceOf(ConflictException.class);assertThatThrownBy(()->s.answer(b.id(),new PrivateWellbeing.Answer(set,1,"stolen",1),false)).isInstanceOf(NotFoundException.class);s.answer(a.id(),new PrivateWellbeing.Answer(set,1,"",1),true);assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_daily_answers WHERE set_id=?",Integer.class,set)).isZero();}
 @Test @Tag("confused") void unreviewedBankIsHonestlyUnavailableAndNoAnswerStoredOnRead(){assertThat(s.daily(a.id(),"UTC","en").get("available")).isEqualTo(false);assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_daily_answers",Integer.class)).isZero();}
 @Test @Tag("creative") void draftsExpireAfterSevenDaysAndConflictRatherThanOverwrite(){s.draft(a.id(),writing("draft",-1,null),false);s.draft(a.id(),writing("changed",0,null),false);assertThatThrownBy(()->s.draft(a.id(),writing("stale",0,null),false)).isInstanceOf(ConflictException.class);assertThat(s.draft(b.id(),null,false).get("items")).asList().isEmpty();db.update("UPDATE wellbeing_journal_drafts SET expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE user_id=?",a.id());s.expireDrafts();assertThat(s.draft(a.id(),null,false).get("items")).asList().isEmpty();}
 @Test @Tag("malicious") void accountRestrictionsAndPayloadBounds(){db.update("UPDATE account_eligibility SET age_result='INELIGIBLE' WHERE user_id=?",a.id());assertThatThrownBy(()->s.history(a.id(),"journal",20,0,"",false)).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->s.write(b.id(),null,writing("x".repeat(20001),0,UUID.randomUUID()))).isInstanceOf(IllegalArgumentException.class);}
 @Test @Tag("happy") void archiveIncludesAllRowsAndErasureIncludesNewCategories(){for(int i=0;i<25;i++)s.write(a.id(),null,writing("private "+i,0,UUID.randomUUID()));s.draft(a.id(),writing("draft",-1,null),false);prompts();UUID set=(UUID)((Map<?,?>)s.daily(a.id(),"UTC","en").get("set")).get("id");s.answer(a.id(),new PrivateWellbeing.Answer(set,1,"private answer",-1),false);assertThat(archive.archive(a.id()).privateWellbeing().get("wellbeing_journal_entries")).asList().hasSize(25);assertThat(archive.archive(b.id()).privateWellbeing().get("wellbeing_journal_entries")).asList().isEmpty();accounts.erase(a.id());assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_daily_answers WHERE set_id=?",Integer.class,set)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM wellbeing_journal_drafts WHERE user_id=?",Integer.class,a.id())).isZero();}
 @Test @Tag("confused") void delayedOnboardingMountCannotUndoExplicitSkip(){db.update("UPDATE user_preferences SET onboarding_status='SKIPPED',onboarding_complete=TRUE WHERE user_id=?",a.id());var initial=json.readValue("{\"onboardingStatus\":\"IN_PROGRESS\"}",com.greenocean.backend.preference.dto.UpdateUserPreferencesRequest.class);preferences.update(a.id(),initial);assertThat(preferences.find(a.id()).orElseThrow().onboardingStatus()).isEqualTo("SKIPPED");}

}
